// Concatenates every migration plus the seed into one file you can paste into
// the Supabase SQL editor in a single go.
//
// Generated on demand and gitignored, never committed: supabase/migrations is
// the source of truth, and a checked-in copy would be a second one that goes
// stale the first time someone edits a migration and forgets this.
//
// Prefer `npx supabase db push` if the CLI is set up — it records which
// migrations ran, so later ones apply incrementally. This bundle does not:
// it is the whole schema from empty, for a database that has never been
// migrated. Running it twice will fail on the first `create table`.
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const DIR = "supabase/migrations";
const OUT = "supabase/bundle.sql";

const files = readdirSync(DIR).filter((f) => f.endsWith(".sql")).sort();

const parts = [
  `-- Tasker — full schema bundle, generated by scripts/db-bundle.mjs`,
  `-- ${files.length} migrations + seed. Paste into the Supabase SQL editor and run once.`,
  `-- Do not edit: change supabase/migrations/ and regenerate with \`npm run db:bundle\`.`,
  "",
  // One transaction, so a failure halfway leaves nothing behind rather than a
  // half-built schema you then have to unpick by hand.
  "begin;",
  "",
];

for (const file of files) {
  parts.push(`-- ===== ${file} ${"=".repeat(Math.max(0, 60 - file.length))}`);
  parts.push(readFileSync(join(DIR, file), "utf8").trim(), "");
}

parts.push(`-- ===== seed.sql ${"=".repeat(52)}`);
parts.push(readFileSync("supabase/seed.sql", "utf8").trim(), "");
parts.push("commit;", "");

writeFileSync(OUT, parts.join("\n"));

const lines = parts.join("\n").split("\n").length;
console.log(`Wrote ${OUT} — ${files.length} migrations + seed, ${lines} lines.`);
console.log("Paste it into the Supabase SQL editor and run it once, on an empty database.");
